"use client"

import * as React from "react"
import gsap from "gsap"
import { ScrollTrigger } from "gsap/ScrollTrigger"

gsap.registerPlugin(ScrollTrigger)

// A scroll-driven decode. The stage pins while the page scrolls; a statement
// starts as fragments of static scattered across the screen, and as you scroll
// each word flies home to its place in the sentence (a FLIP from its scattered
// spot to where it really sits) while its letters churn through noise glyphs,
// then lock in left to right. A headline above decodes first; a HUD counts along.

export type SignalScrambleScrollProps = {
  /** Small headline that decodes first. */
  title?: string
  /** The statement. Wrap words in *asterisks* to light them in the accent. */
  text?: string
  /** HUD labels: top left, bottom left, bottom right. */
  channel?: string
  /** Large outlined figure behind the text. */
  ghost?: string
  coords?: string
  hint?: string
  /** Phosphor colour for the accented words and HUD. */
  accent?: string
  ground?: string
  ink?: string
  /** Page scroll the decode takes, as a multiple of `height`. */
  length?: number
  /** Stage height. Keep it a definite length; percentages collapse once installed. */
  height?: string
  className?: string
}

// #region decode
export const GLYPHS = "ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#%&*+=/<>?{}[]"

/** Deterministic 0..1 from an integer seed. */
export function rand(seed: number): number {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

/** Each word's own 0..1 progress from the overall one: later words start later. */
export function wordProgress(p: number, i: number, n: number, spread = 0.55): number {
  if (n <= 1) return clamp01(p)
  const start = (i / (n - 1)) * spread
  return clamp01((p - start) / (1 - spread))
}

export function clamp01(v: number): number {
  return v < 0 ? 0 : v > 1 ? 1 : v
}

/**
 * The word as shown at progress w: letters before the lock point are real,
 * the rest are noise. Spaces and punctuation stay put so the shape holds.
 */
export function scramble(word: string, w: number, tick: number, from = 0.45, seed = 0): string {
  if (w >= 1) return word
  const locked = Math.floor(clamp01((w - from) / (1 - from)) * word.length)
  let out = ""
  for (let i = 0; i < word.length; i++) {
    const c = word[i]
    if (i < locked || !/[A-Za-z0-9]/.test(c)) out += c
    else out += GLYPHS[Math.floor(rand(tick * 31 + i * 7 + seed * 101 + word.length) * GLYPHS.length)]
  }
  return out
}

export function easeInOut(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

/** Splits "a *b* c" into words, marking accented ones. */
export function tokens(text: string): { word: string; hot: boolean }[] {
  const out: { word: string; hot: boolean }[] = []
  let hot = false
  let closed = false
  for (const part of text.split(/(\*)/)) {
    if (part === "*") {
      closed = hot
      hot = !hot
      continue
    }
    const ws = part.split(/\s+/)
    ws.forEach((w, j) => {
      if (!w) return
      // Text glued to a closing accent mark ("*pattern*,") stays on that word.
      if (j === 0 && closed && out.length && /^\S/.test(part)) out[out.length - 1].word += w
      else out.push({ word: w, hot })
    })
  }
  return out
}
// #endregion

const FONT =
  "@font-face{font-family:'SSS Mono';src:url(data:font/woff2;base64,) format('woff2');font-weight:400;font-display:swap}" +
  "@font-face{font-family:'SSS Mono';src:url(data:font/woff2;base64,) format('woff2');font-weight:700;font-display:swap}"

const CSS =
  FONT +
  ".sss-root{position:relative;width:100%;background:var(--sss-ground);color:var(--sss-ink);font-family:'SSS Mono',ui-monospace,SFMono-Regular,Menlo,monospace}" +
  ".sss-root *{box-sizing:border-box}" +
  ".sss-stage{position:sticky;top:0;width:100%;overflow:hidden;isolation:isolate;display:flex;align-items:center;justify-content:center}" +
  ".sss-scan{position:absolute;inset:0;z-index:0;pointer-events:none;opacity:.5;background:repeating-linear-gradient(0deg,rgba(255,255,255,.028) 0 1px,transparent 1px 3px)}" +
  ".sss-vig{position:absolute;inset:0;z-index:0;pointer-events:none;background:radial-gradient(80% 70% at 50% 50%,transparent 40%,rgba(0,0,0,.7))}" +
  ".sss-glow{position:absolute;left:50%;top:50%;width:70vmin;height:70vmin;z-index:0;pointer-events:none;border-radius:50%;transform:translate(-50%,-50%) scale(var(--sss-g,0.6));opacity:var(--sss-go,0);" +
  "background:radial-gradient(circle,color-mix(in oklab,var(--sss-accent) 22%,transparent),transparent 65%)}" +
  ".sss-ghost{position:absolute;right:-2vmin;top:50%;z-index:0;pointer-events:none;font-weight:700;font-size:62vmin;line-height:1;letter-spacing:-.06em;color:transparent;-webkit-text-stroke:1px color-mix(in oklab,var(--sss-ink) 12%,transparent);transform:translateY(-50%) scale(calc(2.1 - var(--sss-g,.6)))}" +
  ".sss-hud{position:absolute;z-index:2;font-size:11px;letter-spacing:.14em;text-transform:uppercase;opacity:.6;white-space:nowrap}" +
  ".sss-hud b{color:var(--sss-accent);font-weight:700}" +
  ".sss-tl{top:24px;left:28px}.sss-tr{top:24px;right:28px;font-variant-numeric:tabular-nums}.sss-bl{bottom:24px;left:28px}.sss-br{bottom:24px;right:28px}" +
  ".sss-dot{display:inline-block;width:7px;height:7px;margin-right:10px;border-radius:50%;background:var(--sss-accent);box-shadow:0 0 10px var(--sss-accent);animation:sss-blink 1.2s steps(2) infinite}" +
  ".sss-bar{position:absolute;z-index:2;left:28px;right:28px;bottom:56px;height:1px;background:color-mix(in oklab,var(--sss-ink) 14%,transparent)}" +
  ".sss-bar>i{position:absolute;inset:0;background:var(--sss-accent);transform-origin:0 50%;transform:scaleX(0)}" +
  ".sss-body{position:relative;z-index:1;width:min(1100px,100% - 48px)}" +
  ".sss-title{margin:0 0 28px;font-size:13px;font-weight:700;letter-spacing:.32em;text-transform:uppercase;color:var(--sss-accent)}" +
  ".sss-text{margin:0;font-size:clamp(22px,4vw,62px);line-height:1.24;letter-spacing:-.02em;font-weight:400}" +
  ".sss-w{display:inline-block;white-space:pre;will-change:transform,opacity}" +
  ".sss-hot{color:var(--sss-accent);font-weight:700;text-shadow:0 0 18px color-mix(in oklab,var(--sss-accent) 45%,transparent)}" +
  ".sss-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}" +
  "@keyframes sss-blink{50%{opacity:.25}}" +
  "@media (max-width:640px){.sss-hud{font-size:9.5px}.sss-tl,.sss-bl{left:18px}.sss-tr,.sss-br{right:18px}.sss-bar{left:18px;right:18px}.sss-br{display:none}}" +
  "@media (prefers-reduced-motion:reduce){.sss-dot{animation:none}}"

export default function SignalScrambleScroll({
  title = "Incoming transmission",
  text = "Every *signal* starts as noise. We listen long enough to hear the *pattern*, then build the instrument that plays it back to you, *clear*.",
  channel = "CH-07 · receiving",
  ghost = "07",
  coords = "51.5072 N / 0.1276 W",
  hint = "Scroll to decode",
  accent = "#ffb547",
  ground = "#070707",
  ink = "#ece7dc",
  length = 2.6,
  height = "100svh",
  className,
}: SignalScrambleScrollProps) {
  const root = React.useRef(null as HTMLElement | null)
  const toks = React.useMemo(() => tokens(text), [text])

  React.useEffect(() => {
    const el = root.current
    if (!el) return
    const stage = el.querySelector(".sss-stage") as HTMLElement
    const body = el.querySelector(".sss-body") as HTMLElement
    const words = Array.from(el.querySelectorAll(".sss-w")) as HTMLElement[]
    const titleEl = el.querySelector(".sss-title") as HTMLElement | null
    const pct = el.querySelector(".sss-pct") as HTMLElement | null
    const bar = el.querySelector(".sss-bar>i") as HTMLElement | null
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches
    const n = words.length
    // Scatter offsets, measured once per resize: where each word starts relative to its home.
    let offs: { dx: number; dy: number; r: number; s: number }[] = []
    const measure = () => {
      const W = stage.offsetWidth
      const H = stage.offsetHeight
      const bx = body.offsetLeft
      const by = body.offsetTop
      offs = words.map((w, i) => {
        const hx = bx + w.offsetLeft + w.offsetWidth / 2
        const hy = by + w.offsetTop + w.offsetHeight / 2
        const sx = (0.08 + rand(i * 3 + 1) * 0.84) * W
        const sy = (0.1 + rand(i * 3 + 2) * 0.8) * H
        return { dx: sx - hx, dy: sy - hy, r: (rand(i * 3 + 3) - 0.5) * 24, s: 0.35 + rand(i + 9) * 0.35 }
      })
    }
    let tick = 0
    const render = (p: number) => {
      tick++
      const tp = clamp01(p / 0.22)
      if (titleEl) titleEl.textContent = scramble(title, tp, tick, 0.2)
      if (pct) pct.textContent = String(Math.round(p * 100)).padStart(3, "0") + "%"
      if (bar) bar.style.transform = "scaleX(" + p.toFixed(4) + ")"
      stage.style.setProperty("--sss-g", (0.6 + p * 0.6).toFixed(3))
      stage.style.setProperty("--sss-go", (p < 0.95 ? p : 1).toFixed(3))
      for (let i = 0; i < n; i++) {
        const o = offs[i]
        if (!o) continue
        const w = wordProgress(p * 1.12 - 0.04, i, n)
        const e = easeInOut(w)
        const k = 1 - e
        const node = words[i]
        node.style.transform =
          "translate3d(" + (o.dx * k).toFixed(1) + "px," + (o.dy * k).toFixed(1) + "px,0) rotate(" + (o.r * k).toFixed(2) + "deg) scale(" + (o.s + (1 - o.s) * e).toFixed(3) + ")"
        node.style.opacity = (0.28 + 0.72 * Math.min(1, w * 1.6)).toFixed(3)
        const want = scramble(toks[i].word, w, tick, 0.45, i)
        if (node.textContent !== want) node.textContent = want
      }
    }

    if (reduce) {
      if (titleEl) titleEl.textContent = title
      if (pct) pct.textContent = "100%"
      return
    }
    measure()
    const st = ScrollTrigger.create({
      trigger: el,
      start: "top top",
      end: "bottom bottom",
      onUpdate: (self) => render(self.progress),
      onRefreshInit: () => words.forEach((w) => (w.style.transform = "none")),
      onRefresh: (self) => {
        measure()
        render(self.progress)
      },
    })
    // Scrambles keep churning a little while the reader pauses mid-decode.
    const id = window.setInterval(() => {
      const p = st.progress
      if (p > 0 && p < 1 && !document.hidden) render(p)
    }, 90)
    document.fonts?.ready.then(() => ScrollTrigger.refresh())
    render(st.progress)
    return () => {
      window.clearInterval(id)
      st.kill()
      words.forEach((w, i) => {
        w.style.transform = ""
        w.style.opacity = ""
        w.textContent = toks[i].word
      })
    }
  }, [toks, title])

  return (
    <section
      ref={root}
      className={"sss-root" + (className ? " " + className : "")}
      style={{ height: "calc(" + height + " * " + (1 + Math.max(0.5, length)) + ")", "--sss-accent": accent, "--sss-ground": ground, "--sss-ink": ink } as React.CSSProperties}
    >
      <style>{CSS}</style>
      <div className="sss-stage" style={{ height }}>
        <div className="sss-glow" aria-hidden="true" />
        <div className="sss-ghost" aria-hidden="true">
          {ghost}
        </div>
        <div className="sss-scan" aria-hidden="true" />
        <div className="sss-vig" aria-hidden="true" />
        <div className="sss-hud sss-tl" aria-hidden="true">
          <span className="sss-dot" />
          {channel}
        </div>
        <div className="sss-hud sss-tr" aria-hidden="true">
          decoded <b className="sss-pct">000%</b>
        </div>
        <div className="sss-hud sss-bl" aria-hidden="true">
          {coords}
        </div>
        <div className="sss-hud sss-br" aria-hidden="true">
          {hint} ↓
        </div>
        <div className="sss-bar" aria-hidden="true">
          <i />
        </div>
        <div className="sss-body">
          <h2 className="sss-sr">{title}</h2>
          <p className="sss-sr">{toks.map((t) => t.word).join(" ")}</p>
          <div className="sss-title" aria-hidden="true">
            {title}
          </div>
          <p className="sss-text" aria-hidden="true">
            {toks.map((t, i) => (
              <React.Fragment key={i}>
                <span className={"sss-w" + (t.hot ? " sss-hot" : "")}>{t.word}</span>{" "}
              </React.Fragment>
            ))}
          </p>
        </div>
      </div>
    </section>
  )
}
